import itertools, json
jobs='ABCDE'
s=[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]
t=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
idx={j:i for i,j in enumerate(jobs)}
def nominal(p):
 return sum(s[idx[j]][k] for k,j in enumerate(p))+sum(t[idx[a]][idx[b]] for a,b in zip(p,p[1:]))
def legal_cost(p,incident):
 pos={j:p.index(j)+1 for j in jobs}
 if pos['A']>=pos['D']: return None
 if incident=='rain':
  if pos['E']==2 or pos['D']==5:return None
  penalty=6*max(0,pos['A']-2)
 elif incident=='road':
  if pos['B']==5 or pos['D']==1:return None
  penalty=8*max(0,pos['C']-3)
 else:
  if pos['D']==4 or pos['C']==1:return None
  penalty=5*max(0,pos['E']-1)
 return nominal(p)+penalty
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'):continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i];neighbors.append((tuple(q),4))
 repairs={};costs={}
 for inc in ['rain','road','lift']:
  opts=[(v+fee,''.join(q)) for q,fee in neighbors if (v:=legal_cost(q,inc)) is not None]
  if not opts:break
  costs[inc],repairs[inc]=min(opts)
 else:
  results.append((nominal(p)+max(costs.values()),''.join(p),repairs,costs))
results.sort()
best=results[0]
print(json.dumps(dict(roster=best[1],score=best[0],repairs=best[2],repair_costs=best[3],feasible_count=len(results),next_score=min(r[0] for r in results if r[0]>best[0]))))
print('published nominal',nominal(tuple(best[1])))
print('optima',[(r[0],r[1]) for r in results if r[0]==best[0]])

