import itertools,json
start='ACEBD';jobs='ABCDE'
s=[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]
t=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
def dist(q):
 perm=[start.index(x) for x in q];seen=set();cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1;j=i
   while j not in seen:seen.add(j);j=perm[j]
 return 5-cycles
classes={i:[] for i in range(3)}
for q in itertools.permutations(jobs):
 d=dist(q)
 if d>2:continue
 pos={j:q.index(j)+1 for j in jobs}
 if pos['A']>=pos['D'] or pos['E'] in (2,3) or pos['D']==5:continue
 nominal=sum(s[jobs.index(j)][i] for i,j in enumerate(q))+sum(t[jobs.index(a)][jobs.index(b)] for a,b in zip(q,q[1:]))
 cost=nominal+6*max(0,pos['A']-2)+4*d+5*(d==2)
 classes[d].append((cost,''.join(q)))
best=min(x for v in classes.values() for x in v)
# Independently check minimum distances by breadth-first pair exchanges.
levels={start:0};front={start}
for d in (1,2):
 new=set()
 for p in front:
  for i,j in itertools.combinations(range(5),2):
   q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
   if q not in levels:new.add(q)
 for q in new:levels[q]=d
 front=new
for q in itertools.permutations(jobs):
 q=''.join(q)
 assert (levels.get(q,3)==dist(q)) if dist(q)<=2 else q not in levels
print(json.dumps({'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(v)[0] if v else None for d,v in classes.items()},'feasible_by_swaps':{str(d):len(v) for d,v in classes.items()}}))
print(classes)

